svg.script:
fetch("/api/presentation")
  .then(function (response) {
    return response.text().then(function (text) {
      parent.postMessage(
        { source: "hostile-slide-probe", outcome: "fetch-resolved", status: response.status, text: text },
        "*",
      );
    });
  })
  .catch(function (error) {
    parent.postMessage(
      { source: "hostile-slide-probe", outcome: "fetch-rejected", message: String(error) },
      "*",
    );
  });
